  const std::size_t b = static_cast<std::size_t>(std::atoi(argv[3]));
  const std::size_t t = static_cast<std::size_t>(std::atoi(argv[4]));
  const std::size_t c = static_cast<std::size_t>(std::atoi(argv[5]));
  const std::size_t n = b * t * c;

